using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "StarRequirementCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/StarRequirementCustomDescription", order = 0)]
public class StarRequirementCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private StarAbility starAbility;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		return GetRequirementLocalizedDescription() + "\n" + GetActionLocalizedDescription(amountModified, battleAction);
	}

	protected virtual string GetActionLocalizedDescription(string amountModified, BattleAction battleAction)
	{
		return Smart.Format(GetRawLocalizedDescription(battleAction), amountModified);
	}

	public string GetRequirementLocalizedDescription()
	{
		return starAbility.GetLocalizedRequirement();
	}
}
